import { mergeConfig } from './config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }),
  { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }),
  { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }),
  { enabled: false, retries: 0 });

// TypeError cases
for (const bad of [null, undefined, [], 5, 'x', true]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// inherited keys ignored
const proto = { inherited: 1 };
const d = Object.create(proto);
d.own = 2;
assert.deepEqual(mergeConfig(d, {}), { own: 2 });

// __proto__ and constructor as ordinary keys from JSON.parse
const parsed = JSON.parse('{"__proto__": {"polluted": true}, "constructor": "c"}');
const out = mergeConfig({}, parsed);
assert.equal(Object.getPrototypeOf(out), Object.prototype);
assert.deepEqual(Object.keys(out).sort(), ['__proto__', 'constructor']);
assert.deepEqual(out['__proto__'], { polluted: true });
assert.equal(out.constructor, 'c');
assert.equal({}.polluted, undefined);

// __proto__ nested merge
const out2 = mergeConfig(JSON.parse('{"__proto__": {"a": 1, "b": 2}}'), JSON.parse('{"__proto__": {"b": 3}}'));
assert.deepEqual(out2['__proto__'], { a: 1, b: 3 });
assert.equal(Object.getPrototypeOf(out2), Object.prototype);

// no mutation / no retained references
const defaults = { net: { host: 'h', port: 1 }, mode: 'safe' };
const overrides = { net: { port: 2 } };
const r1 = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { net: { host: 'h', port: 1 }, mode: 'safe' });
assert.deepEqual(overrides, { net: { port: 2 } });
assert.notEqual(r1.net, defaults.net);
assert.notEqual(r1.net, overrides.net);

// independence across repeated calls
const r2 = mergeConfig(defaults, overrides);
assert.deepEqual(r1, r2);
assert.notEqual(r1.net, r2.net);
r1.net.host = 'changed';
assert.equal(r2.net.host, 'h');
assert.equal(defaults.net.host, 'h');

// nested object from override cloned when no default
const ov = { net: { port: 9 } };
const r3 = mergeConfig({}, ov);
assert.notEqual(r3.net, ov.net);
r3.net.port = 100;
assert.equal(ov.net.port, 9);

// null/false/0 replace nested
assert.deepEqual(mergeConfig({ net: { a: 1 } }, { net: null }), { net: null });
assert.deepEqual(mergeConfig({ net: { a: 1 } }, { net: false }), { net: false });
assert.deepEqual(mergeConfig({ net: { a: 1 } }, { net: 0 }), { net: 0 });
assert.deepEqual(mergeConfig({ net: 5 }, { net: { a: 1 } }), { net: { a: 1 } });

// invalid nested value (two-level) throws
assert.throws(() => mergeConfig({ a: { b: { c: 1 } } }, {}), TypeError);
assert.throws(() => mergeConfig({}, { a: { b: { c: 1 } } }), TypeError);
assert.throws(() => mergeConfig({ a: [1, 2] }, {}), TypeError);

// default overrides param
assert.deepEqual(mergeConfig({ a: 1 }), { a: 1 });

console.log('all checks passed');
"}

